<?php $real=(int)$resumen['realizadas'];$conf=(int)$resumen['confirmadas'];$tasa=$real>0?$conf*100/$real:0; ?>
<section class="content-header"><h1><i class="fa fa-calendar-check-o"></i> Reporte de reservas</h1></section><section class="content">
<div class="box box-primary no-print"><div class="box-body"><form method="get" class="form-inline"><label>Desde</label> <input type="date" name="desde" class="form-control" value="<?php echo html_escape($filtros['desde']);?>"> <label>Hasta</label> <input type="date" name="hasta" class="form-control" value="<?php echo html_escape($filtros['hasta']);?>"> <select name="ruta_id" class="form-control"><option value="0">Todas las rutas</option><?php foreach($rutas as $r):?><option value="<?php echo $r['ruta_id'];?>" <?php echo $filtros['ruta_id']==$r['ruta_id']?'selected':'';?>><?php echo html_escape($r['ruta_nombre']);?></option><?php endforeach;?></select> <select name="estado" class="form-control"><option value="">Todos los estados</option><?php foreach(array('CONFIRMADA','VENCIDA','CANCELADA','PENDIENTE') as $e):?><option <?php echo $filtros['estado']==$e?'selected':'';?>><?php echo $e;?></option><?php endforeach;?></select> <button class="btn btn-primary"><i class="fa fa-search"></i> Generar</button></form></div></div>
<div class="row"><div class="col-md-3 col-sm-6"><div class="small-box bg-aqua"><div class="inner"><h3><?php echo $real;?></h3><p>Reservas realizadas</p></div></div></div><div class="col-md-3 col-sm-6"><div class="small-box bg-green"><div class="inner"><h3><?php echo $conf;?></h3><p>Confirmadas</p></div></div></div><div class="col-md-3 col-sm-6"><div class="small-box bg-yellow"><div class="inner"><h3><?php echo (int)$resumen['pendientes'];?></h3><p>Pendientes</p></div></div></div><div class="col-md-3 col-sm-6"><div class="small-box bg-red"><div class="inner"><h3><?php echo number_format($tasa,1,',','.');?>%</h3><p>Tasa de conversión</p></div></div></div></div>
<div class="box box-success"><div class="box-header"><h3 class="box-title">Conversión de reservas</h3></div><div class="box-body"><h3 style="margin-top:0"><?php echo number_format($tasa,1,',','.');?>%</h3><div class="progress"><div class="progress-bar progress-bar-success" style="width:<?php echo min(100,$tasa);?>%"></div></div><p><b><?php echo $conf;?></b> reservas convertidas en venta de <b><?php echo $real;?></b> reservas realizadas.</p><p class="text-muted">Vencidas: <b><?php echo (int)$resumen['vencidas'];?></b> &nbsp; Canceladas: <b><?php echo (int)$resumen['canceladas'];?></b> &nbsp; Pendientes: <b><?php echo (int)$resumen['pendientes'];?></b></p></div></div>
<div class="box"><div class="box-header"><h3 class="box-title">Detalle de reservas</h3><div class="pull-right no-print"><button onclick="window.print()" class="btn btn-default btn-sm"><i class="fa fa-print"></i> Imprimir</button> <a class="btn btn-success btn-sm" href="<?php echo site_url('reporte_reservas/csv').'?'.http_build_query($filtros);?>"><i class="fa fa-file-excel-o"></i> Excel/CSV</a></div></div><div class="box-body"><div class="table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>Código</th><th>Fecha reserva</th><th>Límite</th><th>Ruta</th><th class="text-right">Pasajeros</th><th class="text-right">A cuenta</th><th>Estado</th><th>Motivo</th></tr></thead><tbody><?php foreach($detalle as $r):?><tr><td><b><?php echo html_escape($r['codigo']);?></b></td><td><?php echo html_escape($r['fecha_reserva']);?></td><td><?php echo html_escape($r['limite']);?></td><td><?php echo html_escape($r['ruta']);?></td><td class="text-right"><?php echo $r['pasajeros'];?></td><td class="text-right">Bs <?php echo number_format($r['acuenta'],2,',','.');?></td><td><b><?php echo html_escape($r['clasificacion']);?></b></td><td><?php echo html_escape($r['motivo']);?></td></tr><?php endforeach;?></tbody></table></div></div></div></section><style media="print">.no-print,.main-header,.main-sidebar,.content-header,.main-footer{display:none!important}.content-wrapper{margin-left:0!important}.content{padding:0!important}</style>
